function mountHeadline(){const el=$('#headline-visible'),heading=$('#home-headline'),records=homeQuoteRecords(),items=records.map(q=>q.text);if(!el||!heading||!items.length||view!=='home'||query.trim()||homeTypes.size)return;headlineRunner=GumHeadline.create({items,index:headlineIndex,intervalMs:(state.settings.homePhraseSeconds||120)*1000,animate:state.settings.homeTypewriter!==false&&(!state.nativeAppearance||state.nativeAppearance.animations===true)&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches,paused:headlinePaused||state.running||document.hidden||$('#modal')?.open||document.activeElement?.id==='search',write:frame=>{headlineIndex=frame.index;el.textContent=frame.text;heading.setAttribute('aria-label',frame.full);heading.classList.toggle('is-typing',frame.typing);if($('#quote-attribution'))$('#quote-attribution').textContent=GumQuotes.attribution(records[frame.index]);if($('#quote-theme'))$('#quote-theme').textContent=records[frame.index]?.theme||'';}});}
function headlineSettingsHTML(){const mode=GumQuotes.source(state.settings);const chosen=state.settings.homeQuoteBooks??GumQuotes.books.map(b=>b.id);const theme=state.settings.homeQuoteTheme||'';return '<section class="settings-card headline-settings"><h3>Home quotes & phrases</h3><div class="quote-library-actions">'+button('Manage quotes','quote-manager','library','small')+button('Import Excel / JSON','quote-import-file','folder','small')+button('Open quote folder','quote-folder','folder','text small')+button('Reload quote file','quote-reload','refresh','text small')+'</div>'+(state.quoteLibrary?.error?'<div class="hidden-notice error-text" role="alert">'+esc(state.quoteLibrary.error)+'</div>':'')+'<p>Your book collection has '+GumQuotes.quotes.length+' quotes. Choose what Home displays, then save. Quotes and references come from bundled collections and your imports.</p><label class="field">Show on Home<select id="home-quote-source">'+[['books','Book quotes'],['custom','My phrases'],['both','Book quotes and my phrases'],['off','Off']].map(([v,n])=>'<option value="'+v+'" '+(mode===v?'selected':'')+'>'+n+'</option>').join('')+'</select></label><fieldset class="quote-books"><legend>Book categories</legend>'+GumQuotes.books.map(book=>'<label class="check-label"><input type="checkbox" data-quote-book="'+esc(book.id)+'" '+(chosen.includes(book.id)?'checked':'')+'><span>'+esc(book.title)+'<small>'+esc(book.author)+' · '+book.count+' quotes</small></span></label>').join('')+'</fieldset><label class="field">Theme<select id="home-quote-theme"><option value="" '+(!theme?'selected':'')+'>All themes</option>'+GumQuotes.themes.map(t=>'<option value="'+esc(t)+'" '+(theme===t?'selected':'')+'>'+esc(t)+'</option>').join('')+'</select></label><label class="check-label"><input id="home-quote-shuffle" type="checkbox" '+(GumQuotes.shuffleEnabled(state.settings)?'checked':'')+'> Shuffle selected quotes</label><p class="note">'+homeQuoteRecords().length+' quotes currently selected. Book and theme filters apply to book quotes. Save changes to apply your choices.</p><details class="custom-phrase-editor"><summary>My phrases (optional)</summary><label class="field">One phrase per line<textarea id="home-phrases" placeholder="Paste your phrases here, one per line." aria-describedby="headline-limits">'+esc(headlineDraft??(state.settings.homePhrases||[]).join('\n'))+'</textarea></label><p class="note" id="headline-limits">Up to 100 custom phrases, 160 characters each. The imported book quotes retain their full text.</p></details><label class="field">Keep each quote visible (seconds)<input id="home-phrase-seconds" type="number" min="30" max="600" step="1" value="'+(headlineSecondsDraft??state.settings.homePhraseSeconds??120)+'"></label><label class="check-label"><input id="home-typewriter" type="checkbox" '+(state.settings.homeTypewriter!==false?'checked':'')+'> Typewriter animation</label><p class="note">60 seconds is one minute; 120 seconds is two. Reading time starts after typing finishes. Reduced motion shows static text. Search pauses the animation.</p>'+button('Save Home quotes','save-home-phrases','check','primary')+'</section>';}
function quoteManager(){const tokens=GumSearch.terms(quoteManageQuery);const list=GumQuotes.quotes.filter(q=>{const text=GumSearch.normalize([q.text,q.author,q.book,q.theme].join(' '));return tokens.every(t=>text.includes(t));});const position=$('#quote-library-search')?.selectionStart;openDialog('<div class="modal-title"><h2>Quote library</h2>'+iconButton('Close','close-modal','close')+'</div><div class="quote-library-actions">'+button('Add quote','quote-edit','copy','small')+button('Import Excel / JSON','quote-import-file','folder','small')+button('Undo last change','quote-undo','back','small',state.quoteLibrary?.canUndo?'':'disabled')+button('Open quote folder','quote-folder','folder','text small')+button('Reload quote file','quote-reload','refresh','text small')+'</div>'+(state.quoteLibrary?.error?'<p class="error-text" role="alert">'+esc(state.quoteLibrary.error)+'</p>':'')+'<label class="field">Find a quote, author, book or theme<input id="quote-library-search" value="'+esc(quoteManageQuery)+'" placeholder="Search the quote library"></label><p class="note">'+list.length+' quotes. Edits stay on this PC; imports keep existing edits and deletions.</p><div class="quote-manager-list">'+list.slice(0,quoteManageLimit).map(q=>'<article class="quote-manager-row"><p>'+esc(q.text.length>180?q.text.slice(0,180)+'…':q.text)+'</p><small>'+esc(GumQuotes.attribution(q))+'</small><span class="tag">'+esc(q.theme)+'</span><div>'+button('Edit','quote-edit',null,'small','data-id="'+esc(q.id)+'"')+button('Delete','quote-delete',null,'text small','data-id="'+esc(q.id)+'"')+'</div></article>').join('')+'</div>'+(list.length>quoteManageLimit?button('Show 20 more','quote-manager-more',null,'small'):'')+(!list.length?'<p class="note">No matching quotes. Try another search or add one.</p>':''));$('#modal').classList.add('quote-manager-dialog');if(position!==undefined){$('#quote-library-search').focus();try{$('#quote-library-search').setSelectionRange(position,position);}catch{}}}
function quoteEditDialog(id){const q=GumQuotes.quotes.find(q=>q.id===id)||{text:'',author:'',book:'Personal collection',theme:'General',page:'',chapter:'',context:''};openDialog('<div class="modal-title"><h2>'+(id?'Edit quote':'Add a quote')+'</h2>'+iconButton('Close','close-modal','close')+'</div><div class="quote-edit-grid">'+[['text','Quote',2000],['author','Author',200],['book','Book / collection',250],['theme','Theme',200],['page','Page / reference',100],['chapter','Chapter / section',500],['context','Context',6000]].map(([key,label,max])=>'<label class="field '+(['text','context'].includes(key)?'full':'')+'">'+label+(['text','context'].includes(key)?'<textarea id="quote-edit-'+key+'" maxlength="'+max+'">'+esc(q[key])+'</textarea>':'<input id="quote-edit-'+key+'" maxlength="'+max+'" value="'+esc(q[key])+'">')+'</label>').join('')+'</div><div class="quote-library-actions">'+button('Save quote','quote-save','check','primary','data-id="'+esc(id||'')+'"')+button('Back to quote library','quote-manager','back')+'</div>');$('#modal').classList.add('quote-manager-dialog');}
