function homeCategorySuggestions(){const base=state.products.filter(p=>!p.hidden&&!p.archived);const counts=new Map(),all=new Map();for(const p of base){const type=GumCatalog.infer(p).type;all.set(type,(all.get(type)||0)+1);if(!query.trim()||GumSearch.match(p,query,GumCatalog).matches)counts.set(type,(counts.get(type)||0)+1);}const tokens=GumSearch.terms(query);return GumCatalog.types.filter(t=>all.has(t.id)&&!homeTypes.has(t.id)&&(homeCategoriesOpen||counts.has(t.id)||tokens.length&&tokens.every(token=>GumSearch.normalize(t.label).includes(token)))).map(t=>({...t,count:counts.get(t.id)||0,total:all.get(t.id)}));}
