function homeHTML(){const visible=state.products.filter(p=>!p.hidden&&!p.archived),active=homeMode==='find'&&(!!query.trim()||homeTypes.size>0),suggestions=homeCategorySuggestions(),shown=homeCategoriesOpen?suggestions:suggestions.slice(0,6),recent=recentProducts.map(id=>visible.find(p=>p.id===id)).filter(Boolean).slice(0,8),rotated=GumIntent.rediscoverPicks(visible,homeSeed,recentProducts),counts=GumCatalog.types.map(type=>({type,count:visible.filter(p=>GumCatalog.infer(p).type===type.id).length})).filter(x=>x.count).sort((a,b)=>b.count-a.count).slice(0,6),saved=visible.filter(p=>p.saved).length,plan=homeMode==='plan'&&homePlanText?GumIntent.plan(homePlanText,visible,GumCatalog):null,idle=!query.trim()&&!homeTypes.size&&!homePlanText;return '<div class="home-page '+(idle?'is-idle':'is-searching')+' home-v2">'+(state.loadError||state.quoteLibrary?.error?'<div class="hidden-notice error-text" role="alert">'+esc([state.loadError,state.quoteLibrary?.error].filter(Boolean).join(' '))+'</div>':'')+scanBanner()+'<section class="home-hero" aria-label="Search your creative library"><div class="home-aurora" aria-hidden="true"></div><h1 class="home-title">What&#39;s the new creative goal you have?</h1><p class="home-sub home-stats-pills"><span class="home-stat"><b class="count">'+visible.length+'</b> Products to search from</span><span class="home-stat"><b class="count">'+new Set(visible.map(p=>p.creator).filter(Boolean)).size+'</b> Creator Resources</span></p><div class="home-prompt"><div class="search-wrap">'+icon('search')+'<input id="search" class="search" maxlength="300" type="search" autocomplete="off" placeholder="'+(homeMode==='plan'?'Describe your project — e.g. “launch a streetwear brand”':'Search your tools, ideas, and resources…')+'" aria-label="Search your creative library" value="'+esc(query)+'"'+suggestAria()+'>'+suggestHTML()+'</div><div class="home-prompt-bar"><div class="home-mode" role="radiogroup" aria-label="Search mode"><label><input type="radio" name="home-mode" value="find" '+(homeMode==='find'?'checked':'')+'><span>Find</span></label><label><input type="radio" name="home-mode" value="plan" '+(homeMode==='plan'?'checked':'')+'><span>Plan a project</span></label></div><span class="home-prompt-spacer"></span><button class="btn home-category-toggle home-prompt-tool" data-action="home-toggle-categories" aria-expanded="'+homeCategoriesOpen+'" aria-controls="home-category-panel" aria-label="Add a category filter"><span aria-hidden="true">+</span> Category</button>'+((query||homeTypes.size)?iconButton('Clear search and categories','home-clear','close','home-prompt-tool'):'')+'<button class="home-prompt-go" data-action="home-submit" aria-label="Search">'+icon('search')+'</button></div></div>'+(homeTypes.size?'<div class="home-selected-types" aria-label="Selected category filters">'+[...homeTypes].map(id=>{const t=GumCatalog.byId(id);return '<button class="chip type-chip active" style="--type-color:'+t.color+'" data-action="home-remove-type" data-type="'+t.id+'" aria-label="Remove '+esc(t.label)+' filter">'+esc(t.label)+' <span aria-hidden="true">×</span></button>';}).join('')+'</div>':'')+((query.trim()&&shown.length)||homeCategoriesOpen?'<div id="home-category-panel" class="home-category-panel"><div class="section-label">'+(homeCategoriesOpen?'ADD A CATEGORY':'RELATED CATEGORIES')+'</div><div class="home-category-choices">'+shown.map(t=>'<button class="chip type-chip" style="--type-color:'+t.color+'" data-action="home-add-type" data-type="'+t.id+'">+ '+esc(t.label)+' <span>'+t.count+'</span></button>').join('')+'</div></div>':'')+'<div class="home-prompt-chips" aria-label="Try">'+GumIntent.homeTries(visible).map(t=>'<button class="home-try" data-action="home-try" data-text="'+esc(t.text)+'" data-mode="'+esc(t.mode)+'">'+icon(t.mode==='plan'?'folder':'search')+esc(t.text)+'</button>').join('')+'</div></section>'+(idle&&GumQuotes.source(state.settings)!=='off'?'<section class="home-quote-strip" aria-label="Quote">'+headlineMarkup()+quoteAttributionHTML()+homeQuoteActions()+'</section>':'')+(plan?'<section class="home-plan"><h2>For “'+esc(homePlanText)+'” you already own:</h2>'+plan.groups.map(g=>'<div class="home-plan-group"><h3>'+esc(g.type.label)+' <span class="count">'+g.type.count+'</span></h3><div class="home-row">'+g.products.map(homeCard).join('')+'</div></div>').join('')+(plan.unmatchedWords.length?'<p class="note">Unmatched words: '+esc(plan.unmatchedWords.join(', '))+'</p>':'')+'</section>':active?'<div class="home-results-tools"><label>Sort results <select id="sort" class="select" aria-label="Sort search results">'+[['relevance','Best match'],['purchase','Purchase order'],['name','Name, A–Z'],['creator','Creator, A–Z'],['updated','Last scanned']].map(([v,n])=>'<option value="'+v+'" '+(sort===v?'selected':'')+'>'+n+'</option>').join('')+'</select></label><span class="note">Search uses information already collected on this PC.</span></div><div class="content-area '+(selected?'with-detail':'')+'"><div class="collection">'+libraryHTML()+'</div>'+(selected?detailHTML():'')+'</div>':idle?(recent.length?'<section class="home-shelf" aria-labelledby="jump-back-title"><div class="home-shelf-head"><h2 id="jump-back-title">Jump back in</h2></div><div class="home-row '+(recent.length<4?'is-few':'')+'">'+recent.map(homeCard).join('')+'</div></section>':'')+'<section class="home-shelf" aria-labelledby="rediscover-title"><div class="home-shelf-head"><h2 id="rediscover-title">Rediscover</h2><button class="btn text small" data-action="home-shuffle">Shuffle</button></div><div class="home-row">'+rotated.map(homeCard).join('')+'</div></section><section class="home-shelf" aria-labelledby="shelves-title"><div class="home-shelf-head"><h2 id="shelves-title">Your shelves</h2></div><div class="home-tiles">'+counts.map(({type,count})=>'<button class="home-tile" data-action="browse-type" data-type="'+esc(type.id)+'" style="--type-color:'+esc(type.color)+'">'+icon(window.GumVisuals?.categoryIcon(type.id)||'categories')+esc(type.label)+' <span class="count">'+count+'</span></button>').join('')+(saved?'<button class="home-tile" data-action="view" data-view="saved">'+icon('saved')+'Saved <span class="count">'+saved+'</span></button>':'')+'</div></section><footer class="home-stats"><span><b class="count">'+visible.length+'</b> resources</span><span><b class="count">'+new Set(visible.map(p=>p.creator).filter(Boolean)).size+'</b> creators</span><span><b class="count">'+saved+'</b> saved</span><span>Last scan '+esc(state.lastScan?new Date(state.lastScan).toLocaleDateString():'—')+'</span></footer>':'')+'</div>';}

function savedCollectionsHTML(){const collections=state.collections||[];if(savedCollection&&!collections.some(c=>c.id===savedCollection))savedCollection='';const current=collections.find(c=>c.id===savedCollection);const visibleSaved=state.products.filter(p=>p.saved&&!p.hidden);return '<section class="saved-collections" aria-label="Saved collections"><div class="collection-heading"><span class="eyebrow">YOUR COLLECTIONS</span>'+button('New collection','new-collection','folder','small')+'</div><div class="saved-collection-list"><button class="chip '+(!savedCollection?'active':'')+'" data-action="saved-collection" data-id="">All saved <span>'+visibleSaved.length+'</span></button>'+collections.map(c=>'<button class="chip '+(c.id===savedCollection?'active':'')+'" data-action="saved-collection" data-id="'+esc(c.id)+'">'+esc(c.name)+' <span>'+visibleSaved.filter(p=>c.productIds.includes(p.id)).length+'</span></button>').join('')+'</div>'+(current?'<div class="collection-heading"><span class="note">'+esc(current.name)+'</span><div>'+button('Rename','rename-collection',null,'text small','data-id="'+esc(current.id)+'"')+button('Remove collection','delete-collection',null,'text small','data-id="'+esc(current.id)+'"')+'</div></div>':'<p class="note">Organize a product from its details panel. A product can belong to more than one collection.</p>')+'</section>';}
function collectionNameDialog(id=''){const c=(state.collections||[]).find(c=>c.id===id);openDialog('<div class="modal-title"><h2>'+(c?'Rename collection':'A place for your favorites.')+'</h2>'+iconButton('Close','close-modal','close')+'</div><label class="field">Collection name<input id="collection-name" maxlength="60" value="'+esc(c?.name||'')+'" placeholder="For example, My next brand project"></label>'+button(c?'Save name':'Create collection','save-collection-name','check','primary','data-id="'+esc(id)+'"'));$('#collection-name').focus();}
function organizeDialog(id){const p=byId(id);if(!p||p.hidden)return;openDialog('<div class="modal-title"><h2>Keep it close.</h2>'+iconButton('Close','close-modal','close')+'</div><p>'+esc(p.name)+'</p><div class="organize-options">'+(state.collections||[]).map(c=>'<label class="check-label"><input type="checkbox" data-membership="'+esc(c.id)+'" '+(c.productIds.includes(p.id)?'checked':'')+'>'+esc(c.name)+'</label>').join('')+'</div>'+(!(state.collections||[]).length?'<p>Create a collection below to start organizing.</p>':'')+'<label class="field">New collection (optional)<input id="organize-new-name" maxlength="60" placeholder="Collection name"></label>'+button(p.saved?'Save changes':'Save product','save-organization','check','primary','data-id="'+esc(id)+'"')+(p.saved?' '+button('Remove from saved','unsave-product','saved','text','data-id="'+esc(id)+'"'):'')+'<p class="note">Save without selecting a collection to keep this product in All saved. Adding to a collection also bookmarks this product. Unchecking every collection keeps it in All saved. Unsave removes it from every collection.</p>');}
